#!/usr/bin/env sh
# fetch Municipalityofanasco~Pr~Us (US) GTFS -> gtfs.zip. Regenerated by build_repo.py.
URL="https://www.municipiodeanasco.com/_files/archives/7d32eb_1c433dd599ef45ce98ffbd7032df005e.zip?dn=Anasco.zip"
DIR="$(CDPATH= cd "$(dirname "$0")" && pwd)"
echo "GET $URL"
curl -fSL --retry 3 --max-time 300 -o "$DIR/gtfs.zip" "$URL" || { echo "download failed"; exit 1; }
unzip -l "$DIR/gtfs.zip" 2>/dev/null | grep -q stops.txt || { echo "not valid GTFS (no stops.txt)"; exit 2; }
echo "ok: $DIR/gtfs.zip"
